# claude 20261115: minimal Netflix-style replacement for Elementum's buffering DialogProgress.
# Same interface Elementum uses (create / update / iscanceled / close); no seeds / speeds on screen.
import json
import os
import re
import sys
import threading
import urllib.parse
import urllib.request

import xbmc
import xbmcaddon
import xbmcgui

from elementum.addon import ADDON_PATH

ACTION_BACK = (9, 10, 92, 110)


def _art():
    """Artwork remembered by the skin's Play button (Window(Home).Property(NF.Load.*)), else the focused item."""
    home = xbmcgui.Window(10000)
    out = {k: home.getProperty('NF.Load.%s' % k) for k in ('poster', 'fanart', 'clearlogo', 'title', 'year')}
    try:  # only trust it if Play was pressed in the last 2 minutes (otherwise it belongs to an older movie)
        import time as _t
        h, m, sec = [int(x) for x in home.getProperty('NF.Load.time').split(':')]
        now = _t.localtime()
        age = (now.tm_hour * 3600 + now.tm_min * 60 + now.tm_sec) - (h * 3600 + m * 60 + sec)
        if not 0 <= age <= 120:
            out = {}
    except Exception:
        out = {}
    # (not cleared here: Elementum opens several progress dialogs per playback - searching, then buffering)
    if out.get('fanart') or out.get('poster'):
        return out

    def first(*labels):
        for l in labels:
            v = xbmc.getInfoLabel(l)
            if v:
                return v
        return ''
    return {
        'poster': first('ListItem.Art(poster)', 'ListItem.Art(tvshow.poster)'),
        'fanart': first('ListItem.Art(fanart)', 'ListItem.Art(landscape)'),
        'clearlogo': first('ListItem.Art(clearlogo)', 'ListItem.Art(tvshow.clearlogo)'),
        'title': first('ListItem.TVShowTitle', 'ListItem.Title', 'ListItem.Label'),
        'year': xbmc.getInfoLabel('ListItem.Year'),
    }

def _tmdb_lookup(text):
    """Guess title (+year / SxxEyy) from the torrent name and fetch backdrop + logo from TMDb."""
    m = re.search(r'([A-Za-z0-9][A-Za-z0-9 ._\'&!,:-]*?)[ ._(\[]+(?:S(\d{1,2})E\d{1,3}|((?:19|20)\d\d))', text, re.I)
    if not m:
        return {}
    title = re.sub(r'[._]+', ' ', m.group(1)).strip()
    is_tv, year = bool(m.group(2)), m.group(3)
    kf = os.path.join(xbmcaddon.Addon('plugin.video.themoviedb.helper').getAddonInfo('path'),
                      'resources', 'tmdbhelper', 'lib', 'api', 'api_keys', 'tmdb.py')
    API_KEY = re.search(r"API_KEY\s*=\s*['\"]([0-9a-f]{32})['\"]", open(kf).read()).group(1)

    def get(path, **q):
        q['api_key'] = API_KEY
        url = 'https://api.themoviedb.org/3/%s?%s' % (path, urllib.parse.urlencode(q))
        return json.loads(urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent': 'Kodi'}), timeout=8).read().decode('utf-8'))
    kind = 'tv' if is_tv else 'movie'
    q = {'query': title}
    if year and not is_tv:
        q['year'] = year
    res = (get('search/%s' % kind, **q).get('results') or [])
    if not res:
        return {}
    r = res[0]
    out = {'title': r.get('title') or r.get('name') or title,
           'year': (r.get('release_date') or r.get('first_air_date') or '')[:4]}
    if r.get('poster_path'):
        out['poster'] = 'https://image.tmdb.org/t/p/w500' + r['poster_path']
    if r.get('backdrop_path'):
        out['fanart'] = 'https://image.tmdb.org/t/p/w1280' + r['backdrop_path']
    try:
        logos = get('%s/%s/images' % (kind, r['id']), include_image_language='en,null').get('logos') or []
        if logos:
            out['clearlogo'] = 'https://image.tmdb.org/t/p/w500' + logos[0]['file_path']
    except Exception:
        pass
    return out


MAX_FALLBACK = 3     # claude 20261122: after a few-seeds cancel, try the next source up to this many times
STALL_SECS = 60      # claude 20261122: no progress for this long -> give up (few seeds)
SLOW_SECS = 150      # ...or still under SLOW_PCT after this long
SLOW_PCT = 10


class NFLoading(xbmcgui.WindowXMLDialog):
    def __init__(self, *args, **kwargs):
        self._canceled = False
        self._closed = False
        self._pct = 0
        self._art = kwargs.get('art') or {}
        self._ready = threading.Event()
        self._t0 = self._tlast = __import__('time').time()

    def onInit(self):
        for k, v in self._art.items():
            self.setProperty(k, v or '')
        self._apply()
        self._ready.set()

    def _apply(self):
        try:
            self.getControl(20).setPercent(self._pct)
        except Exception:
            pass
        self.setProperty('status', 'Cancelling…' if self._canceled else ('Loading  %d%%' % self._pct if self._pct > 0 else 'Loading'))

    def onAction(self, action):
        if action.getId() in ACTION_BACK:
            self._cancel()

    def _cancel(self, reason=None):
        if self._canceled:
            return
        self._canceled = True
        self._apply()
        if reason:
            xbmc.log('[NFLoading] auto-cancel: %s' % reason, xbmc.LOGWARNING)
            if not self._fallback():
                xbmcgui.Dialog().notification("Elementum", reason, xbmcgui.NOTIFICATION_WARNING, 5000)

    def _fallback(self):
        home = xbmcgui.Window(10000)
        url = home.getProperty("NF.FB.play")
        try:
            n = int(home.getProperty("NF.FB.skip") or 0) + 1
        except Exception:
            n = 1
        if not url or "/play/" not in url or n > MAX_FALLBACK:
            return False
        home.setProperty("NF.FB.skip", str(n))
        links = url.replace("/play/", "/links/", 1)
        xbmcgui.Dialog().notification("Elementum", "Too few sources - trying next (%d/%d)" % (n, MAX_FALLBACK), xbmcgui.NOTIFICATION_INFO, 4000)
        threading.Thread(target=self._replay, args=(links,), daemon=True).start()
        return True

    def _replay(self, links):
        mon = xbmc.Monitor()
        for _ in range(30):  # wait for Elementum to close this screen and drop the stalled torrent
            if self._closed or mon.waitForAbort(0.5):
                break
        if mon.waitForAbort(2.5):
            return
        xbmcgui.Window(10000).setProperty("NF.FB.pending", str(__import__("time").time()))
        xbmc.log("[NFLoading] fallback: %s" % links, xbmc.LOGWARNING)
        xbmc.executebuiltin("PlayMedia(%s)" % links)

    # claude 20261122: run modally in its own thread - with show() from Elementum's RPC thread
    # onAction never fired, so Back could not cancel and the user was stuck behind this screen
    def _run(self):
        try:
            self.doModal()
        finally:
            self._closed = True
            self._ready.set()

    def _watchdog(self):
        import time
        mon = xbmc.Monitor()
        while not self._closed and not self._canceled and not mon.waitForAbort(1):
            now = time.time()
            if now - self._tlast > STALL_SECS:
                self._cancel('Too few sources - stalled, cancelled')
            elif now - self._t0 > SLOW_SECS and self._pct < SLOW_PCT:
                self._cancel('Too few sources - too slow, cancelled')

    # --- DialogProgress interface ---
    def create(self, heading='', message=''):
        for k, v in self._art.items():
            self.setProperty(k, v or '')
        threading.Thread(target=self._run, daemon=True).start()
        self._ready.wait(5)
        self._apply()
        threading.Thread(target=self._watchdog, daemon=True).start()
        self._maybe_lookup('%s %s' % (heading, message))

    def _lookup(self, text):
        try:
            art = _tmdb_lookup(text)
            for k, v in art.items():
                self.setProperty(k, v)
        except Exception as e:
            xbmc.log('[NFLoading] lookup failed: %s' % e, xbmc.LOGWARNING)

    def _maybe_lookup(self, text):
        if (self._art.get('fanart') and self._art.get('poster')) or getattr(self, '_looked', False) or not text:
            return
        if re.search(r'(?:19|20)\d\d|S\d{1,2}E\d', text, re.I):
            self._looked = True
            threading.Thread(target=self._lookup, args=(text,), daemon=True).start()

    def update(self, percent=0, message=''):
        self._maybe_lookup(message)
        try:
            p = max(0, min(100, int(percent)))
            if p > self._pct:
                self._tlast = __import__('time').time()
            self._pct = p
        except Exception:
            pass
        self._apply()

    def iscanceled(self):
        return self._canceled

    def close(self):
        self._closed = True
        try:
            xbmcgui.WindowXMLDialog.close(self)
        except Exception:
            pass


def create(heading, message):
    dlg = NFLoading('nf_loading.xml', ADDON_PATH, 'Default', '1080i', art=_art())
    dlg.create(heading, message)
    return dlg
